import json
import sys

def deep_merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        result = a.copy()
        for key, value in b.items():
            if key in result:
                result[key] = deep_merge(result[key], value)
            else:
                result[key] = value
        return result
    elif isinstance(a, list) and isinstance(b, list):
        result = a[:]
        for item in b:
            if item not in result:
                result.append(item)
        return result
    else:
        return b

