import Foundation

let filePath = "/tmp/…/app.log"

func solve() {
    let content = (try? String(contentsOfFile: filePath, encoding: .utf8)) ?? ""
    let lines = content.components(separatedBy: .newlines)

    var levelCounts = [String: Int]()
    var componentErrorCounts = [String: Int]()
    var uniqueErrorMessages = Set<String>()
    var hourCounts = [Int: Int]()

    for line in lines {
        if line.trimmingCharacters(in: .whitespaces).isEmpty { continue }

        let parts1 = line.components(separatedBy: "] ")
        if parts1.count < 2 { continue }
        let timestamp = parts1[0].replacingOccurrences(of: "[", with: "")
        let rest = parts1[1]

        let parts2 = rest.components(separatedBy: " (")
        if parts2.count < 2 { continue }
        let level = parts2[0]
        let rest2 = parts2[1]

        levelCounts[level, default: 0] += 1

        let timeParts = timestamp.components(separatedBy: " ")
        if timepartsCount(timeParts) {
            let timeString = timeParts[1]
            let hourParts = timeString.components(separatedBy: ":")
            if let hour = Int(hourParts[0]) {
                hourCounts[hour, default: 0] += 1
            }
        }

        let separator = ") - "
        if let range = rest2.range(of: separator) {
            let component = String(rest2[..<range.lowerBound])
            let message = String(rest2[range.upperBound...])

            if level == "ERROR" {
                componentErrorCounts[component, default: 0] += 1
                uniqueErrorMessages.insert(message)
            }
        }
    }

    print("=== Log Analysis ===")
    print("")

    print("Entries by Level:")
    let sortedLevelNames = levelCounts.keys.sorted()
    for name in sortedLevelNames {
        print("  \(name): \(levelCounts[name]!)")
    }

    print("")

    if let topComponent = componentErrorCounts.sorted(by: {
        if $0.value != $1.value {
            return $0.value > $1.value
        }
        return $0.key < $1.key
    }).first {
        print("Component with Most Errors: \(topComponent.key) (\(topComponent.value) errors)")
    }

    print("")

    print("Unique Error Messages:")
    let sortedMessages = uniqueErrorMessages.sorted()
    for msg in sortedMessages {
        print("  - \(msg)")
    }

    print("")

    if let topHour = hourCounts.sorted(by: {
        if $0.value != $1.value {
            return $0.value > $1.value
        }
        return $0.key < $1.key
    }).first {
        let hourString = String(format: "%02d:00", topHour.key)
        print("Busiest Hour: \(hourString) (\(topHour.value) entries)")
    }
}

func timepartsCount(_ parts: [String]) -> Bool {
    return parts.count >= 2
}

