struct Employee {
    name: String,
    department: String,
    salary: f64,
}

fn main() {
    let path = "/tmp/…/employees.csv";
    let file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return,
    };
    let reader = BufReader::new(file);
    let mut employees = Vec::new();

    for (i, line) in reader.lines().enumerate() {
        let line = match line {
            Ok(l) => l,
            Err(_) => break,
        };
        if i == 0 || line.trim().is_empty() {
            continue;
        }

        let cols: Vec<&str> = line.split(',').collect();
        if cols.len() < 6 {
            continue;
        }

        let name = cols[1].trim().to_string();
        let dept = cols[2].trim().to_string();
        let salary: f64 = cols[3].trim().parse().unwrap_or(0.0);

        employees.push(Employee {
            name,
            department: dept,
            salary,
        });
    }

    let mut dept_sums: BTreeMap<String, f64> = BTreeMap::new();
    let mut dept_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut total_budget: f64 = 0.0;
    let mut highest_paid_val: f64 = -1.0;
    let mut highest_paid_name = String::new();

    for emp in &employees {
        *dept_sums.entry(emp.department.clone()).or_insert(0.0) += emp.salary;
        *dept_counts.entry(emp.department.clone()).or_insert(0) += 1;
        total_budget += emp.salary;

        if emp.salary > highest_paid_val {
            highest_paid_val = emp.salary;
            highest_paid_name = emp.name.clone();
        }
    }

    println!("=== Salary Report ===");
    println!("");
    println!("Average Salary by Department:");
    for (dept, sum) in &dept_sums {
        let count = dept_counts[dept];
        let avg = sum / count as f64;
        println!("  {}: ${}", dept, format_float_with_commas(avg));
    }
    println!("");
    println!("Highest Paid: {} (${})", highest_paid_name, format_int_with_commas(highest_paid_val as i64));
    println!("");
    println!("Departments with >2 employees:");
    for (dept, count) in &dept_counts {
        if *count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }
    println!("");
    println!("Total Budget: ${}", format_int_with_commas(total_budget as i64));
}

import java.util.*;
import java.io.*;
import java.nio.file.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String pathA = "/tmp/…/config_a.json";
        String pathB = "/tmp/…/config_b.json";

        String jsonA = Files.readString(Path.of(pathA));
        String jsonB = Files.readString(Path.of(pathB));

        Object objA = new JsonParser(jsonA).parse();
        Object objB = new JsonParser(jsonB).parse();

        Object merged = merge(objA, objB);

        StringBuilder sb = new StringBuilder();
        serialize(merged, sb, 0);
        System.out.print(sb.toString());
    }

    static Object merge(Object a, Object b) {
        if (a instanceof Map && b instanceof Map) {
            Map<String, Object> res = new TreeMap<>();
            Map<String, Object> mapA = (Map<String, Object>) a;
            Map<String, Object> mapB = (Map<String, Object>) b;

            for (String key : mapA.keySet()) {
                res.put(key, mapA.get(key));
            }
            for (String key : mapB.keySet()) {
                if (mapA.containsKey(key)) {
                    res.put(key, merge(mapA.get(key), mapB.get(key)));
                } else {
                    res.put(key, mapB.get(key));
                }
            }
            return res;
        } else if (a instanceof List && b instanceof List) {
            List<Object> res = new ArrayList<>((List<Object>) a);
            for (Object itemB : (List<Object>) b) {
                if (!res.contains(itemB)) {
                    res.add(itemB);
                }
            }
            return res;
        } else {
            return b;
        }
    }

    static String escape(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t").replace("\b", "\\b").replace("\f", "\\f");
    }

    static void serialize(Object value, StringBuilder sb, int indent) {
        if (value == null) {
            sb.append("null");
        } else if (value instanceof Map) {
            Map<String, Object> map = (Map<String, Object>) value;
            if (map.isEmpty()) {
                sb.append("{}");
            } else {
                sb.append("{\n");
                List<String> keys = new ArrayList<>(map.keySet());
                for (int i = 0; i < keys.size(); i++) {
                    String key = keys.get(i);
                    sb.append("  ".repeat(indent + 1)).append("\"").append(escape(key)).append("\": ");
                    serialize(map.get(key), sb, indent + 1);
                    if (i < keys.size() - 1) sb.append(",");
                    sb.append("\n");
                }
                sb.append("  ".repeat(indent)).append("}");
            }
        } else if (value instanceof List) {
            List<Object> list = (List<Object>) value;
            if (list.isEmpty()) {
                sb.append("[]");
            } else {
                sb.append("[\n");
                for (int i = 0; i < list.size(); i++) {
                    sb.append("  ".repeat(indent + 1));
                    serialize(list.get(i), sb, indent + 1);
                    if (i < list.size() - 1) sb.append(",");
                    sb.append("\n");
                }
                sb.append("  ".repeat(indent)).append("]");
            }
        } else if (value instanceof String) {
            sb.append("\"").append(escape((String) value)).append("\"");
        } else if (value instanceof Double) {
            Double d = (Double) value;
            if (d == Math.floor(d) && !Double.isInfinite(d) && !Double.isNaN(d)) {
                sb.append(d.longValue());
            } else {
                sb.append(d.toString());
            }
        } else if (value instanceof Long) {
            sb.append(value.toString());
        } else {
            sb.append(value.toString());
        }
    }

    static class JsonParser {
        String input;
        int pos = 0;

        JsonParser(String input) { this.input = input; }

        Object parse() {
            skipWhitespace();
            if (pos >= input.length()) return null;
            char c = input.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't' || c == 'f') return parseBoolean();
            if (c == 'n') return parseNull();
            return parseNumber();
        }

        void skipWhitespace() {
            while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) {
                pos++;
            }
        }

        Map<String, Object> parseObject() {
            Map<String, Object> map = new TreeMap<>();
            pos++; 
            skipWhitespace();
            if (pos < input.length() && input.charAt(pos) == '}') {
                pos++;
                return map;
            }
            while (true) {
                String key = parseString();
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == ':') pos++;
                skipWhitespace();
                Object value = parse();
                map.put(key, value);
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == '}') {
                    pos++;
                    break;
                }
                if (pos < input.length() && input.charAt(pos) == ',') {
                    pos++;
                    skipWhitespace();
                }
            }
            return map;
        }

        List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            pos++; 
            skipWhitespace();
            if (pos < input.length() && input.charAt(pos) == ']') {
                pos++;
                return list;
            }
            while (true) {
                Object value = parse();
                list.add(value);
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == ']') {
                    pos++;
                    break;
                }
                if (pos < input.length() && input.charAt(pos) == ',') {
                    pos++;
                    skipWhitespace();
                }
            }
            return list;
        }

        String parseString() {
            pos++; 
            StringBuilder sb = new StringBuilder();
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (c == '"') {
                    pos++;
                    return sb.toString();
                }
                if (c == '\\') {
                    pos++;
                    char escaped = input.charAt(pos);
                    if (escaped == '"') sb.append('"');
                    else if (escaped == '\\') sb.append('\\');
                    else if (escaped == '/') sb.append('/');
                    else if (escaped == 'b') sb.append('\b');
                    else if (escaped == 'f') sb.append('\f');
                    else if (escaped == 'n') sb.append('\n');
                    else if (escaped == 'r') sb.append('\r');
                    else if (escaped == 't') sb.append('\t');
                    else if (escaped == 'u') {
                        String hex = input.substring(pos + 1, pos + 5);
                        sb.append((char) Integer.parseInt(hex, 16));
                        pos += 4;
                    } else {
                        sb.append(escaped);
                    }
                    pos++;
                } else {
                    sb.append(c);
                    pos++;
                }
            }
            return sb.toString();
        }

        boolean parseBoolean() {
            if (input.startsWith("true", pos)) {
                pos += 4;
                return true;
            } else {
                pos += 5;
                return false;
            }
        }

        Object parseNull() {
            pos += 4;
            return null;
        }

        Object parseNumber() {
            int start = pos;
            if (pos < input.length() && input.charAt(pos) == '-') pos++;
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (Character.isDigit(c) || c == '.' || c == 'e' || c == 'E' || c == '+') {
                    pos++;
                } else {
                    break;
                }
            }
            String numStr = input.substring(start, pos);
            if (numStr.toLowerCase().contains("e") || numStr.contains(".")) {
                return Double.parseDouble(numStr);
            } else {
                return Long.parseLong(numStr);
            }
        }
    }
}

import Foundation

let filePath = "/tmp/…/employees.csv"

struct Employee {
    let name: String
    let department: String
    let salary: Double
}

func run() {
    guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
        return
    }

    let lines = content.components(separatedBy: .newlines).filter { !$0.isEmpty }
    guard lines.count > 1 else {
        return
    }

    var employees: [Employee] = []
    for i in 1..<lines.count {
        let columns = lines[i].components(separatedBy: ",")
        if columns.count >= 4 {
