    intFormatter.numberStyle = .decimal
    intFormatter.minimumFractionDigits = 0
    intFormatter.maximumFractionDigits = 0
    intFormatter.locale = Locale(identifier: "en_US_POSIX")

    print("=== Salary Report ===")
