        let avg = deptTotals[dept]! / Double(deptCounts[dept]!)
        let formattedAvg = avgFormatter.string(from: NSNumber(value: avg)) ?? ""
        print("  \(dept): $\(formattedAvg)")
    }
    print("")
    if let hp = highestPaidEmployee {
        let formattedSalary = intFormatter.string(from: NSNumber(value: hp.salary)) ?? ""
        print("Highest Paid: \(hp.name) ($\(formattedSalary))")
    }
    print("")
    print("Departments with >2 employees:")
    let sortedLargeDepts = deptCounts.keys.filter { deptCounts[$0]! > 2 }.sorted()
    for dept in sortedLargeDepts {
        print("  \(dept) (\(deptCounts[dept]!) employees)")
    }
    print("")
    let formattedTotal = intFormatter.string(from: NSNumber(value: totalBudget)) ?? ""
    print("Total Budget: $\(formattedTotal)")
}

