    const parts = line.split(',');
    if (parts.length < 4) continue;

    const name = parts[1].trim();
    const dept = parts[2].trim();
    const salary = parseFloat(parts[3].trim());

    totalBudget += salary;

    if (salary > highestPaidSalary) {
      highestPaidSalary = salary;
      highestPaidName = name;
    }

    const stats = deptStats.get(dept) || { sum: 0, count: 0 };
    stats.sum += salary;
    stats.count += 1;
    deptStats.set(dept, stats);
