use std::fs::File;
use std::io::{BufRead, BufReader};
use std::collections::{BTreeMap, BTreeSet, HashMap};

fn main() {
    let path = "/tmp/…/app.log";
    let file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return,
    };
    let reader = BufReader::new(file);

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_component_counts: HashMap<String, usize> = HashMap::new();
    let mut unique_error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts = [0usize; 24];

    for line_result in reader.lines() {
        let line = match line_result {
            Ok(l) => l,
            Err(_) => break,
        };
        if line.trim().is_empty() {
            continue;
        }

        if let Some(end_bracket_idx) = line.find(']') {
            let timestamp = &line[1..end_bracket_idx];
            if timestamp.len() >= 13 {
                if let Ok(hour) = timestamp[11..13].parse::<usize>() {
                    if hour < 24 {
                        hour_counts[hour] += 1;
                    }
                }
            }

            let rest = &line[end_bracket_idx + 1..].trim_start();
            if let Some((level, comp_msg)) = rest.split_once(" (") {
                if let Some((component, message)) = comp_msg.split_once(") - ") {
                    let level_str = level.to_string();
                    *level_counts.entry(level_str.clone()).or_insert(0) += 1;

                    if level_str == "ERROR" {
                        *error_component_counts.entry(component.to_string()).or_insert(0) += 1;
                        unique_error_messages.insert(message.to_string());
                    }
                }
            }
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let mut error_components: Vec<_> = error_component_counts.iter().collect();
    error_components.sort_by(|a, b| b.1.cmp(a.1).then_with(|| a.0.cmp(b.0)));
    if let Some(&(comp, count)) = error_components.first() {
        println!("Component with Most Errors: {} ({} errors)", comp, count);
    }

    println!();
    println!("Unique Error Messages:");
    for msg in &unique_error_messages {
        println!("  - {}", msg);
    }
    println!();

    let mut max_hour_count = 0;
    let mut busiest_hour = 0;
    for (h, &count) in hour_counts.iter().enumerate() {
        if count > max_hour_count {
            max_hour_count = count;
            busiest_hour = h;
        }
    }
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, max_hour_count);
}

import json
import heapq

def solve():
    file_path = "/tmp/…/graph.json"

    with open(file_path, 'r') as f:
        data = json.load(f)

    nodes = data["nodes"]
    edges = data["edges"]

    adj = {node: [] for node in nodes}
    for edge in edges:
        u, v, w = edge["from"], edge["to"], edge["weight"]
        adj[u].append((v, w))
        adj[v].append((u, w))

    distances = {node: float('inf') for node in nodes}

    if "A" in distances:
        distances["A"] = 0
        pq = [(0, "A")]

        while pq:
            d, u = heapq.heappop(pq)
            if d > distances[u]:
                continue
            for v, w in adj[u]:
                if distances[u] + w < distances[v]:
                    distances[v] = distances[u] + w
                    heapq.heappush(pq, (distances[v], v))

    print("=== Shortest Paths from A ===")
    print()

    for node in sorted(nodes):
        print(f"A -> {node}: {distances[node]}")

