#include <string.h>

typedef struct {
    char *dept_name;
    double total_salary;
    int count;
} Dept;

void format_comma(char *dest, double val, int precision) {
    char temp[256];
    sprintf(temp, "%.*f", precision, val);

    char *dot = strchr(temp, '.');
    int dot_pos = dot ? (int)(dot - temp) : (int)strlen(temp);
    int sign_len = (temp[0] == '-') ? 1 : 0;
    int int_len = dot_pos - sign_len;

    char result[256];
    int r_idx = 0;
    if (sign_len) result[r_idx++] = '-';

    for (int i = 0; i < int_len; i++) {
        if (i > 0 && i % 3 == 0) {
            result[r_idx++] = ',';
        }
        result[r_idx++] = temp[sign_len + int_len - 1 - i];
    }

    int left = sign_len;
    int right = r_idx - 1;
    while (left < right) {
        char t = result[left];
        result[left] = result[right];
        result[right] = t;
        left++;
        right--;
    }

    if (dot) {
        strcpy(result + r_idx, dot);
    }
    strcpy(dest, result);
}

int compare_depts(const void *a, const void *b) {
    return strcmp(((Dept *)a)->dept_name, ((Dept *)b)->dept_name);
}

