    char *top_name = NULL;
    double top_salary = -1.0;
    double total_budget = 0;

    while (fgets(line, sizeof(line), fp)) {
        line[strcspn(line, "\r\n")] = 0;
        char *parts[6];
        int p = 0;
        char *token = strtok(line, ",");
        while (token && p < 6) {
            parts[p++] = token;
            token = strtok(NULL, ",");
        }
        if (p < 4) continue;

        char *name = parts[1];
        char *dept_name = parts[2];
        double salary = atof(parts[3]);

        total_budget += salary;

        if (salary > top_salary) {
            top_salary = salary;
            if (top_name) free(top_name);
            top_name = strdup(name);
        }

        int found = -1;
        for (int i = 0; i < dept_count; i++) {
            if (strcmp(depts[i].dept_name, dept_name) == 0) {
                found = i;
                break;
            }
        }

        if (found != -1) {
            depts[found].total_salary += salary;
            depts[found].count++;
        } else {
            dept_count++;
            depts = realloc(depts, sizeof(Dept) * dept_count);
            depts[dept_count - 1].dept_name = strdup(dept_name);
            depts[dept_count - 1].total_salary = salary;
            depts[dept_count - 1].count = 1;
        }
    }
    fclose(fp);

    qsort(depts, dept_count, sizeof(Dept), compare_depts);

