    for (int i = 0; i < dept_count; i++) {
        double avg = depts[i].total_salary / depts[i].count;
        format_comma(buf, avg, 2);
        printf("  %s: $%s\n", depts[i].dept_name, buf);
    }
    printf("\n");

    format_comma(buf, top_salary, 0);
    printf("Highest Paid: %s ($%s)\n", top_name ? top_name : "", buf);
    printf("\n");

    printf("Departments with >2 employees:\n");
    for (int i = 0; i < dept_count; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].dept_name, depts[i].count);
        }
    }
    printf("\n");

    format_comma(buf, total_budget, 0);
    printf("Total Budget: $%s\n", buf);

    if (top_name) free(top_name);
    for (int i = 0; i < dept_count; i++) {
        free(depts[i].dept_name);
    }
    free(depts);

    return 0;
}

