use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum Value {
    Object(BTreeMap<String, Value>),
    Array(Vec<s::Value>), // This is a typo, should be Value
    Array(Vec<Value>),
    String(String),
    Number(f64),
    Bool(bool),
    Null,
}

// Re-defining to ensure no typos
#[derive(Debug, Clone, PartialEq)]
enum ValueType {
    Object(BTreeMap<String, ValueType>),
    Array(Vec<ValueType>),
    String(String),
    Number(f64),
    Bool(bool),
    Null,
}

// Using a simpler name to avoid confusion
type Val = ValueType;

struct Parser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Self { input, pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.input.chars().nth(self.pos)
    }

    fn consume(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += c.len_utf8();
        Some(c)
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.consume();
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> Val {
        self.skip_whitespace();
        let c = self.peek().unwrap_or(' ');
        match c {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => self.parse_string(),
            't' | 'f' | 'n' => self.parse_literal(),
            _ => self.parse_number(),
        }
    }

    fn parse_string(&mut self) -> Val {
        Val::String(self.parse_string_content())
    }

    fn parse_string_content(&mut self) -> String {
        self.consume(); // "
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c == '"' {
                self.consume();
                return s;
            }
            if c == '\\' {
                self.consume();
                let esc = self.consume().unwrap_or(' ');
                match esc {
                    'n' => s.push('\n'),
                    'r' => s.push('\r'),
                    't' => s.push('\t'),
                    '\\' => s.push('\\'),
                    '"' => s.push('"'),
                    _ => s.push(esc),
                }
            } else {
                s.push(self.consume().unwrap_or(' '));
            }
        }
        s
    }

    fn parse_object(&mut self) -> Val {
        self.consume(); // {
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.consume();
            return Val::Object(map);
        }
        loop {
            let key = self.parse_string_content();
            self.skip_whitespace();
