#[derive(Debug, Clone, PartialEq)]
enum Value {
    Object(Bect<String, Value>),
    Array(Vec<Value>),
    String(String),
    Number(f64),
    Bool(bool),
    Null,
}

// Using a more direct name for the type to avoid confusion
type Val = Value;

#[derive(Debug, Clone, PartialEq)]
enum Bect<K, V> {
    Object(BTreeMap<K, V>),
    Array(Vec<V>),
    String(String),
    Number(f64),
    Bool(bool),
    Null,
}

// Re-defining to ensure no typos and clear structure
#[derive(Debug, Clone, PartialEq)]
enum ValueType {
    Object(BTreeMap<String, ValueType>),
    Array(Vec<ValueType>),
    String(String),
    Number(f64),
    Bool(bool),
    Null,
}

// Using the correct type throughout the program
type ValType = ValueType;

#[derive(Debug, Clone, PartialEq)]
enum ValueFinal {
    Object(BTreeMap<String, ValueFinal>),
    Array(Vec<ValueFinal>),
    String(String),
    Number(f64),
    Bool(bool),
    Null,
}

struct Parser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Self { input, pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.input.chars().nth(self.pos)
    }

    fn consume(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += c.len_utf8();
        Some(c)
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.consume();
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> ValueFinal {
        self.skip_whitespace();
        let c = self.peek().unwrap_or(' ');
        match c {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => self.parse_string(),
            't' | 'f' | 'n' => self.parse_literal(),
            _ => self.parse_number(),
        }
    }

    fn parse_string(&mut self) -> ValueFinal {
        ValueFinal::String(self.parse_string_content())
    }

    fn parse_string_content(&mut self) -> String {
        self.consume(); // consume opening "
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c == '"' {
                self.consume(); // consume closing "
                return s;
            }
            if c == '\\' {
                self.consume(); // consume \
                if let Some(esc) = self.consume() {
                    match esc {
                        'n' => s.push('\n'),
                        'r' => s.push('\r'),
                        't' => s.push('\t'),
                        '\\' => s.push('\\'),
                        '"' => s.push('"'),
                        _ => s.push(esc),
                    }
                }
            } else {
                if let Some(c) = self.consume() {
                    s.push(c);
                }
            }
        }
        s
    }

    fn parse_object(&mut self) -> ValueFinal {
        self.consume(); // {
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.consume();
            return ValueFinal::Object(map);
        }
        loop {
            let key = self.parse_string_content();
            self.skip_whitespace();
            self.consume(); // :
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_whitespace();
            match self.peek() {
                Some(',') => { self.consume(); },
                Some('}') => { self.consume(); break; },
                _ => break,
            }
        }
        ValueFinal::Object(map)
    }

    fn parse_array(&mut self) -> ValueFinal {
        self.consume(); // [
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.consume();
            return ValueFinal::Array(arr);
        }
        loop {
            let val = self.parse_value();
            arr.push(val);
            self.skip_whitespace();
            match self.peek() {
                Some(',') => { self.consume(); },
                Some(']') => { self.consume(); break; },
                _ => break,
            }
        }
        ValueFinal::Array(arr)
    }

    fn parse_literal(&mut self) -> ValueFinal {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_alphabetic() {
                s.push(self.consume().unwrap());
            } else {
                break;
            }
        }
        match s.as_str() {
            "true" => ValueFinal::Bool(true),
            "false" => ValueFinal::Bool(false),
            "null" => ValueFinal::Null,
            _ => ValueFinal::Null,
        }
    }

    fn parse_number(&mut self) -> ValueFinal {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_digit(10) || c == '.' || c == '-' || c == '+' || c == 'e' || c == 'E' {
                s.push(self.consume().unwrap());
            } else {
                break;
            }
        }
        let n: f64 = s.parse().unwrap_or(0.0);
        ValueFinal::Number(n)
    }
}

fn merge(a: ValueFinal, b: ValueFinal) -> ValueFinal {
    match (a, b) {
        (ValueFinal::Object(mut map_a), ValueFinal::Object(map_b)) => {
            for (k, v) in map_b {
                if let Some(old_v) = map_a.remove(&k) {
                    map_a.insert(k, merge(old_v, v));
