import java.io.IOException;
import java.nio.file.*;
import java.util.*;

public class Main {
    static class FileEntry {
        String relPath;
        long lines;
        long bytes;

        FileEntry(String relPath, long lines, long bytes) {
            this.relPath = relPath;
            this.lines = lines;
            this.bytes = bytes;
        }
    }

    public static void main(String[] args) {
        Path root = Paths.get("/tmp/…/project_tree");
        TreeMap<String, List<FileEntry>> extensionMap = new TreeMap<>();
        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        try (var stream = Files.walk(root)) {
            List<Path> allFiles = new ArrayList<>();
            stream.forEach(path -> {
                if (Files.isRegularFile(path)) {
                    allFiles.add(path);
                }
            });

            for (Path path : allFiles) {
                String filename = path.getFileName().toString();
                int dotIndex = filename.lastIndexOf('.');
                String ext = (dotIndex == -1) ? "" : filename.substring(dotIndex);

                byte[] bytes = Files.readAllBytes(path);
                long size = bytes.length;
                long lines = 0;
                if (size > 0) {
                    lines = 1;
                    for (int i = 0; i < size - 1; i++) {
                        if (bytes[i] == '\n') {
                            lines++;
                        }
                    }
                }

                String relPath = root.relativize(path).toString().replace('\\', '/');
                extensionMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileEntry(relPath, lines, size));
                totalFiles++;
                totalLines += lines;
                totalChars += size;
            }
        } catch (IOException e) {
            // Error handled by silent completion as per requirements
        }

        System.out.println("=== File Tree Analysis ===");
        System.out.println();

        for (Map.Entry<String, List<FileEntry>> entry : extensionMap.entrySet()) {
            List<FileEntry> files = entry.getValue();
            Collections.sort(files, Comparator.comparing(f -> f.relPath));

            long extFiles = files.size();
            long extLines = 0;
            long extChars = 0;
            for (FileEntry f : files) {
                extLines += f.lines;
                extChars += f.bytes;
            }

            System.out.println("Extension: " + entry.getKey());
            System.out.println("  Files: " + extFiles);
            System.out.println("  Total Lines: " + extLines);
            System.out.println("  Total Characters: " + extChars);
            for (FileEntry f : files) {
                System.out.println("    " + f.relPath + ": " + f.lines + " lines, " + f.bytes + " chars");
            }
        }

        System.out.println();
        System.out.println("Total: " + totalFiles + " files, " + totalLines + " lines, " + totalChars + " characters");
    }
}

