#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/**
 * Runs a shell command and returns the output as a dynamically allocated string.
 * The trailing newline and whitespace characters are stripped.
 */
char* run_command(const char* cmd) {
    char* buffer = malloc(1024);
    if (!buffer) {
        return NULL;
    }
    buffer[0] = '\0';

    FILE* fp = popen(cmd, "r");
    if (!fp) {
        free(buffer);
        return NULL;
    }

    // fgets reads up to 1023 characters
    if (fgets(buffer, 1024, fp) != NULL) {
        size_t len = strlen(buffer);
        // Strip trailing newline, carriage return, or space
        while (len > 0 && (buffer[len - 1] == '\n' || buffer[len - 1] == '\r' || buffer[len - 1] == ' ')) {
            buffer[--len] = '\0';
        }
    }

    pclose(fp);
    return buffer;
}

int main(void) {
    char* hostname = run_command("hostname");
    char* os = run_command("uname -s");
    char* architecture = run_command("uname -m");
    char* username = run_command("whoami");

    // Output the JSON object with 2-space indentation
    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", hostname ? hostname : "");
    printf("  \"os\": \"%s\",\n", os ? os : "");
    printf("  \"architecture\": \"%s\",\n", architecture ? architecture : "");
    printf("  \"username\": \"%s\"\n", username ? username : "");
    printf("}\n");

    // Clean up allocated memory
    if (hostname) free(hostname);
    if (os) free(os);
    if (architecture) free(architecture);
    if (username) free(username);

    return 0;
}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) {
        String hostname = execute("hostname");
        String os = execute("uname", "-s");
        String architecture = execute("uname", "-m");
        String username = execute("whoami");

        System.out.println("{");
        System.out.println("  \"hostname\": \"" + hostname + "\",");
        System.out.println("  \"os\": \"" + os + "\",");
        System.out.println("  \"architecture\": \"" + architecture + "\",");
        System.out.println("  \"username\": \"" + username + "\"");
        System.out.println("}");
    }

    private static String execute(String... command) {
        try {
            ProcessBuilder pb = new ProcessBuilder(command);
            Process process = pb.start();
            String line = null;
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                line = reader.readLine();
            }
            process.waitFor();
            return (line != null) ? line.trim() : "";
        } catch (Exception e) {
            return "";
        }
    }
}

