typedef struct {
    char name[256];
    double price;
} Product;

int compareProducts(const void *a, const void *b) {
    const Product *p1 = (const Product *)a;
    const Product *p2 = (const Product *)b;
    return strcmp(p1->name, p2->name);
}

int main(void) {
    int sock = 0;
    struct sockaddr_in serv_addr;
    const char *request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n";

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) return 1;

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(18923);

    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {
        close(sock);
        return 1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        close(sock);
        return 1;
    }

    send(sock, request, strlen(request), 0);

    size_t buffer_size = 8192;
    char *buffer = malloc(buffer_size);
    if (!buffer) {
        close(sock);
        return 1;
    }

    size_t total_received = 0;
    ssize_t received;

    while ((received = recv(sock, buffer + total_received, buffer_size - total_received - 1, 0)) > 0) {
        total_received += received;
        if (total_received >= buffer_size - 1) {
            buffer_size *= 2;
            char *new_buf = realloc(buffer, buffer_size);
            if (!new_buf) {
                free(buffer);
                close(sock);
                return 1;
            }
            buffer = new_buf;
        }
    }
    buffer[total_received] = '\0';
    close(sock);

    char *body = strstr(buffer, "\r\n\r\n");
    if (body) {
        body += 4;
    } else {
        body = buffer;
    }

    Product *filtered = NULL;
    int count = 0;
    double total_sum = 0.0;

    char *obj_start = strchr(body, '{');
    while (obj_start) {
        char *obj_end = strchr(obj_start, '}');
        if (!obj_end) break;

        char *n_key = strstr(obj_start, "\"name\":\"");
        char *p_key = strstr(obj_start, "\"price\":");

        if (n_key && n_key < obj_end && p_key && p_key < obj_end) {
            char *n_val_start = n_key + 8;
            char *n_val_end = strchr(n_val_start, '\"');

            if (n_val_end && n_val_end < obj_end) {
                double p_val = atof(p_key + 8);
                if (p_val > 50.00) {
                    filtered = realloc(filtered, sizeof(Product) * (count + 1));
                    size_t len = n_val_end - n_val_start;
                    if (len >= 256) len = 255;
                    strncpy(filtered[count].name, n_val_start, len);
                    filtered[count].name[len] = '\0';
                    filtered[count].price = p_val;
                    total_sum += p_val;
                    count++;
                }
            }
        }
        obj_start = strchr(obj_end + 1, '{');
    }

    if (count > 0) {
        qsort(filtered, count, sizeof(Product), compareProducts);
    }

    printf("=== Filtered Products (price > $50.00) ===\n\n");
    for (int i = 0; i < count; i++) {
        printf("%s: $%.2f\n", filtered[i].name, filtered[i].price);
    }
    if (count > 0) printf("\n");
    printf("Count: %d\n", count);
    printf("Total: $%.2f\n", total_sum);

    free(buffer);
    if (count > 0) free(filtered);

    return 0;
}

