use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

fn walk(
    current_dir: &Path,
    root_path: &Path,
    results: &mut BTreeMap<String, BTreeMap<String, (usize, usize)>>,
    total_files: &mut usize,
    total_lines: &mut usize,
    total_chars: &mut usize,
) {
    if let Ok(entries) = fs::read_dir(current_dir) {
        let mut entries: Vec<_> = entries.filter_map(|e| e.ok()).collect();
        // Sort entries to ensure deterministic traversal
        entries.sort_by_key(|e| e.path());

        for entry in entries {
            let path = entry.path();
            let file_type = match entry.file_type() {
                Ok(ft) => ft,
                Err(_) => continue,
            };

            if file_type.is_dir() {
                if !file_type.is_symlink() {
                    walk(&path, root_path, results, total_files, total_lines, total_chars);
                }
            } else if file_type.is_file() {
                if !file_type.is_symlink() {
                    let ext = path
                        .extension()
                        .map(|e| format!(".{}", e.to_string_lossy()))
                        .unwrap_or_else(|| "".to_string());

                    let relative_path = path
                        .strip_prefix(root_path)
                        .unwrap_or(&path)
                        .to_string_lossy()
                        .replace('\\', "/");

                    if let Ok(bytes) = fs::read(&path) {
                        let lines = bytes.iter().filter(|&&b| b == b'\n').count();
                        let chars = bytes.len();

                        results
                            .entry(ext)
                            .or_default()
                            .insert(relative_path, (lines, chars));
                        *total_files += 1;
                        *total_lines += lines;
                        *total_chars += chars;
                    }
                }
            }
        }
    }
}

fn main() {
    let root_path = Path::new("/tmp/…/project_tree");

    let mut results: BTreeMap<String, BTreeMap<String, (usize, usize)>> = BTreeMap::new();
    let mut total_files: usize = 0;
    let mut total_lines: usize = 0;
    let mut total_chars: usize = 0;

    walk(root_path, root_path, &mut results, &mut total_files, &mut total_lines, &mut total_chars);

    println!("=== File Tree Analysis ===");
    println!();

    for (ext, files) in &results {
        println!("Extension: {}", ext);
        let mut ext_files = 0;
        let mut ext_lines = 0;
        let mut ext_chars = 0;

        for (_, (lines, chars)) in files {
            ext_files += 1;
            ext_lines += lines;
            ext_chars += chars;
        }

        println!("  Files: {}", ext_files);
        println!("  Total Lines: {}", ext_lines);
        println!("  Total Characters: {}", ext_chars);

        for (rel_path, (lines, chars)) in files {
            println!("    {}: {} lines, {} chars", rel_path, lines, chars);
        }
    }

    println!();
    println!(
        "Total: {} files, {} lines, {} characters",
        total_files, total_lines, total_chars
    );
}

def multiply(A, B):
    size = len(A)
    C = [[0] * size for _ in range(size)]
    for i in range(size):
        for j in range(size):
            for k in range(size):
                C[i][j] += A[i][k] * B[k][j]
    return C

def determinant_3x3(M):
    a, b, c = M[0][0], M[0][1], M[0][2]
    d, e, f = M[1][0], M[1][1], M[1][2]
    g, h, i = M[2][0], M[2][1], M[2][2]
    return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)

def main():
    A = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    B = [[9, 8, 7], [6, 5, 4], [3, 2, 1]]

    C = multiply(A, B)
    det_C = determinant_3x3(C)

    print("=== Matrix Operations ===")
    print()
    print("Matrix A:")
    for row in A:
        print("  " + " ".join(f"{v:4d}" for v in row))
    print()
    print("Matrix B:")
    for row in B:
        print("  " + " ".join(f"{v:4d}" for v in row))
    print()
    print("A x B =")
    for row in C:
        print("  " + " ".join(f"{v:4d}" for v in row))
    print()
    print(f"Determinant: {det_C}")

