use std::collections::{HashMap, BinaryHeap};
use std::cmp::Reverse;
use std::fs;

fn extract_string(s: &str, key: &str) -> Option<String> {
    let key_pattern = format!("\"{}\"", key);
    if let Some(start_idx) = s.find(&key_pattern) {
        let colon_offset = s[start_idx..].find(':').unwrap();
        let absolute_colon_idx = start_idx + colon_offset;
        let val_start_search = &s[absolute_colon_idx..];
        if let Some(quote_start_idx) = val_start_search.find('"') {
            let val_start = absolute_colon_idx + quote_start_idx + 1;
            if let Some(quote_end_idx) = s[val_start..].find('"') {
                return Some(s[val_start..val_start + quote_end_idx].to_string());
            }
        }
    }
    None
}

fn extract_number(s: &str, key: &str) -> Option<u64> {
    let key_pattern = format!("\"{}\"", key);
    if let Some(start_idx) = s.find(&key_pattern) {
        let colon_offset = s[start_idx..].find(':').unwrap();
        let absolute_colon_idx = start_idx + colon_offset;
        let val_start = absolute_colon_idx + 1;
        let remaining = &s[val_start..];
        let end_idx = remaining.find(|c: char| c == ',' || c == '}' || c == ']' || c == ' ' || c == '\n' || c == '\r')
            .unwrap_or(remaining.len());
        let val_str = remaining[..end_idx].trim();
        return val_str.parse::<u64>().ok();
    }
    None
}

fn main() {
    let path = "/tmp/…/graph.json";
    let content = fs::read_to_string(path).expect("Failed to read file");

    let nodes_start_tag = "\"nodes\": [";
    let nodes_start_idx = content.find(nodes_start_tag).unwrap() + nodes_start_tag.len();
    let nodes_end_idx = content[nodes_start_idx..].find(']').unwrap() + nodes_start_idx;
    let nodes_raw = &content[nodes_start_idx..nodes_end_idx];

    let mut nodes = Vec::new();
    for part in nodes_raw.split(',') {
        let trimmed = part.trim().trim_matches(|c: char| c == '[' || c == ']' || c == ' ' || c == '"');
        if !trimmed.is_empty() {
            nodes.push(trimmed.to_string());
        }
    }

    let edges_start_tag = "\"edges\": [";
    let edges_start_idx = content.find(edges_start_tag).unwrap() + edges_start_tag.len();
    let edges_end_idx = content[edges_start_idx..].rfind(']').unwrap() + edges_start_idx;
    let edges_raw = &content[edges_start_idx..edges_end_idx];

    let mut edges_list = Vec::new();
    for edge_obj in edges_raw.split('}') {
        let edge_obj = edge_obj.trim();
        if edge_obj.is_empty() || edge_obj == "{" || edge_obj == "[" || edge_obj == "," {
            continue;
        }
        let f = extract_string(edge_obj, "from");
        let t = extract_string(edge_obj, "to");
        let w = extract_number(edge_obj, "weight");
        if let (Some(f_val), Some(t_val), Some(w_val)) = (f, t, w) {
            edges_list.push((f_val, t_val, w_val));
        }
    }

    let mut node_to_idx = HashMap::new();
    for (i, node) in nodes.iter().enumerate() {
        node_to_idx.insert(node.clone(), i);
    }

    let mut adj = vec![vec![]; nodes.len()];
    for (f, t, w) in edges_list {
        if let (Some(&u), Some(&v)) = (node_to_idx.get(&f), node_to_idx.get(&t)) {
            adj[u].push((v, w));
            adj[v].push((u, w));
        }
    }

    let start_node_name = "A";
    let start_idx = *node_to_idx.get(start_node_name).expect("Start node 'A' not found");

    let mut dists = vec![u64::MAX; nodes.len()];
    dists[start_idx] = 0;
    let mut pq = BinaryHeap::new();
    pq.push(Reverse((0, start_idx)));

    while let Some(Reverse((d, u))) = pq.pop() {
        if d > dists[u] {
            continue;
        }
        for &(v, w) in &adj[u] {
            if dists[u] + w < dists[v] {
                dists[v] = dists[u] + w;
                pq.push(Reverse((dists[v], v)));
            }
        }
    }

    println!("=== Shortest Paths from A ===");
    println!();

    let mut results: Vec<(String, u64)> = nodes.iter()
        .map(|name| (name.clone(), dists[node_to_idx[name]]))
        .collect();

    results.sort_by(|a, b| a.0.cmp(&b.0));

    for (name, d) in results {
        println!("{} -> {}: {}", start_node_name, name, d);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_NUMBER,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} json_type;

typedef struct json_node json_node;

typedef struct {
    char *key;
    json_node *value;
} json_pair;

struct json_node {
    json_type type;
    union {
        bool b_val;
        double d_val;
        char *s_val;
        struct {
            json_pair *pairs;
            size_t count;
        } object;
        struct {
            json_node *elements;
            size_t count;
        } array;
    } val;
};

void free_node(json_node *node) {
    if (!node) return;
    if (node->type == JSON_STRING) {
        free(node->val.s_val);
    } else if (node->type == JSON_OBJECT) {
        for (size_t i = 0; i < node->val.object.count; i++) {
            free(node->val.object.pairs[i].key);
            free_node(node->val.object.pairs[i].value);
        }
        free(node->val.object.pairs);
    } else if (node->type == JSON_ARRAY) {
        for (size_t i = 0; i < node->val.array.count; i++) {
            free_node(&node->val.array.elements[i]);
        }
        free(node->val.array.elements);
    }
    free(node);
}

json_node* copy_node(const json_node *src) {
    json_node *res = malloc(sizeof(json_node));
    res->type = src->type;
    if (src->type == JSON_NULL) {
    } else if (src->type == JSON_BOOL) {
        res->val.b_val = src->val.b_val;
    } else if (src->type == JSON_NUMBER) {
        res->val.d_val = src->val.d_val;
    } else if (src->type == JSON_STRING) {
        res->val.s_val = strdup(src->val.s_val);
    } else if (src->type == JSON_ARRAY) {
        res->val.array.count = src->val.array.count;
        res->val.array.elements = NULL;
        if (src->val.array.count > 0) {
            res->val.array.elements = malloc(sizeof(json_node) * src->val.array.count);
            for (size_t i = 0; i < src->val.array.count; i++) {
                res->val.array.elements[i] = *copy_node(&src->val.array.elements[i]);
            }
        }
    } else if (src->type == JSON_OBJECT) {
        res->val.object.count = src->val.object.count;
        res->val.object.pairs = malloc(sizeof(json_pair) * src->val.object.count);
        for (size_t i = 0; i < src->val.object.count; i++) {
            res->val.object.pairs[i].key = strdup(src->val.object.pairs[i].key);
            res->val.object.pairs[i].value = copy_node(src->val.object.pairs[i].value);
        }
    }
    return res;
}

bool is_equal(const json_node *a, const json_node *b) {
    if (a->type != b->type) return false;
    if (a->type == JSON_NULL) return true;
    if (a->type == JSON_BOOL) return a->val.b_val == b->val.b_val;
    if (a->type == JSON_NUMBER) return a->val.d_val == b->val.d_val;
    if (a->type == objString) return strcmp(a->val.s_val, b->val.s_val) == 0;
    if (a->type == JSON_ARRAY) {
        if (a->val.array.count != b->val.array.count) return false;
        for (size_t i = 0; i < a->val.array.count; i++) {
            if (!is_equal(&a->val.array.elements[i], &b->val.array.elements[i])) return false;
        }
        return true;
    }
    if (a->type == JSON_OBJECT) {
        if (a->val.object.count != b->val.object.count) return false;
        for (size_t i = 0; i < a->val.object.count; i++) {
            bool found = false;
            for (size_t j = 0; j < b->val.object.count; j++) {
                if (strcmp(a->val.object.pairs[i].key, b->val.object.pairs[j].key) == 0) {
                    if (!is_equal(a->val.object.pairs[i].value, b->val.object.pairs[j].value)) return false;
                    found = true;
                    break;
                }
            }
            if (!found) return false;
        }
        return true;
    }
    return false;
}

// Helper for is_equal to handle cases where we compare a pointer-to-node vs a pointer-to-node
// but our structure uses a mix of pointers and embedded objects.
// The logic above handles it if we treat everything as a pointer to a node.

// Let's redefine is_equal to always take pointers.
bool is_equal_ptr(const json_node *a, const json_node *b) {
    if (a->type != b->type) return false;
    if (a->type == JSON_NULL) return true;
    if (a->type == JSON_BOOL) return a->val.b_val == b->val.b_val;
    if (a->type == JSON_NUMBER) return a->val.d_val == b->val.d_val;
    if (a->type == JSON_STRING) return strcmp(a->val.s_val, b->val.s_val) == 0;
    if (a->type == JSON_ARRAY) {
        if (a->val.array.count != b->val.array.count) return false;
        for (size_t i = 0; i < a->val.array.count; i++) {
            if (!is_equal_ptr(&a->val.array.elements[i], &b->val.array.elements[i])) return false;
        }
        return true;
    }
    if (a->type == JSON_OBJECT) {
        if (a->val.object.count != b->val.object.count) return false;
        for (size_t i = 0; i < a->val.object.count; i++) {
            bool found = false;
            for (size_t j = 0; j < b->val.object.count; j++) {
                if (strcmp(a->val.object.pairs[i].key, b->val.object.pairs[j].key) == 0) {
                    if (!is_equal_ptr(a->val.object.pairs[i].value, b->val.object.pairs[j].value)) return false;
                    found = true;
                    break;
                }
            }
            if (!found) return false;
        }
        return true;
    }
    return false;
}

// Since we can't use the above easily with the 'embedded' array elements, 
// let's use a helper that handles both.
bool is_equal_any(const json_node *a, const json_node *b) {
    return is_equal_ptr(a, b);
}

json_pair* find_pair(json_node *obj, const char *key) {
    if (obj->type != JSON_OBJECT) return NULL;
    for (size_t i = 0; i < obj->val.object.count; i++) {
        if (strcmp(obj->val.object.pairs[i].key, key) == 0) return &obj->val.object.pairs[i];
    }
    return NULL;
}

void add_pair(json_node *obj, const char *key, json_node *val) {
    obj->val.object.pairs = realloc(obj->val.object.pairs, sizeof(json_pair) * (obj->val.object.count + 1));
    obj->val.object.pairs[obj->val.object.count].key = strdup(key);
    obj->val.object.pairs[obj->val.object.count].value = val;
    obj->val.object.count++;
}

void add_item(json_node *obj, json_node *val) {
    obj->val.array.elements = realloc(obj->val.array.elements, sizeof(json_node) * (obj->val.array.count + 1));
    obj->val.array.elements[obj->val.array.count] = *val;
    obj->val.array.count++;
}

// The merge function as defined in the requirements.
json_node* merge(json_node *a, json_node *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        for (size_t i = 0; i < b->val.object.count; i++) {
            json_pair *existing = find_pair(a, b->val.object.pairs[i].key);
            if (existing) {
                json_node *merged = merge(existing->value, b->val.object.pairs[i].value);
                if (merged != existing->value) {
                    // If type changed, the old value was freed inside merge.
                    // We just update the pointer.
                    existing->value = merged;
                } else {
                    // If it's the same (e.g. both were scalars), merge just returns 'a'.
                    // But the prompt says 'b' overrides 'a' for scalars.
                    // Our merge handles that by returning the new node.
                }
            } else {
                add_pair(a, b->val.object.pairs[i].key, copy_node(b->val.object.pairs[i].value));
            }
        }
        return a;
    } else if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        for (size_t i = 0; i < b->val.array.count; i++) {
            bool found = false;
            for (size_t j = 0; j < a->val.array.count; j++) {
                if (is_equal_ptr(&a->val.array.elements[j], &b->val.array.elements[i])) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                add_item(a, copy_node(&b->val.array.elements[i]));
            }
        }
        return a;
    } else {
        json_node *new_val = copy_node(b);
        free_node(a);
        return new_val;
    }
}

// Parser
const char* skip_ws(const char* s) {
    while (*s && (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r')) s++;
    return s;
}

json_node* parse_json(const char **s);

char* parse_string(const char **s) {
    (*s)++; // skip "
    size_t len = 0;
    char *buf = malloc(1024);
    while (**s && **s != '"') {
        if (**s == '\\') {
            (*s)++;
            if (**s == 'n') buf[len++] = '\n';
            else if (**s == 'r') buf[len++] = '\r';
            else if (**s == 't') buf[len++] = '\t';
            else if (**s == '\\') buf[len++] = '\\';
            else if (**s == '"') buf[len++] = '"';
            else buf[len++] = **s;
        } else {
            buf[len++] = **s;
        }
        (*s)++;
    }
    buf[len] = '\0';
    if (**s == '"') (*s)++;
    return buf;
}

json_node* parse_json(const char **s) {
    *s = skip_ws(*s);
    json_node *node = malloc(sizeof(json_node));
    if (**s == '{') {
        node->type = JSON_OBJECT;
        node->val.object.count = 0;
        node->val.object.pairs = NULL;
        (*s)++;
        *s = skip_ws(*s);
        while (**s && **s != '}') {
            char *key = parse_string(s);
            *s = skip_ws(*s);
            (*s)++; // skip :
            *s = skip_ws(*s);
            json_node *val = parse_json(s);
            add_pair(node, key, val);
            free(key);
            *s = skip_ws(*s);
            if (**s == ',') (*s)++;
            *s = skip_ws(*s);
        }
        if (**s == '}') (*s)++;
    } else if (**s == '[') {
        node->type = JSON_ARRAY;
        node->val.array.count = 0;
        node->val.array.elements = NULL;
        (*s)++;
        *s = skip_ws(*s);
        while (**s && **s != ']') {
            json_node *val = parse_json(s);
            add_item(node, val);
            *s = skip_ws(*s);
            if (**s == ',') (*s)++;
            *s = skip_ws(*s);
        }
        if (**s == ']') (*s)++;
    } else if (**s == '"') {
        node->type = JSON_STRING;
        node->val.s_val = parse_string(s);
    } else if (strncmp(*s, "true", 4) == 0) {
        node->type = JSON_BOOL;
        node->val.b_val = true;
        *s += 4;
    } else if (strncmp(*s, "false", 5) == 0) {
        node->type = JSON_BOOL;
        node->val.b_val = false;
        *s += 5;
    } else if (strncmp(*s, "null", 4) == 0) {
        node->type = JSON_NULL;
        *s += 4;
    } else {
        node->type = JSON_NUMBER;
        char buf[128];
        int i = 0;
        while (**s && **s != ',' && **s != '}' && **s != ']' && **s != ' ' && **s != '\n' && **s != '\r' && **s != '\t') {
            buf[i++] = *(*s)++;
        }
        buf[i] = '\0';
        node->val.d_val = atof(buf);
    }
    return node;
