        for (size_t i = 0; i < b->val.object.count; i++) {
            json_pair *existing = NULL;
            for (size_t j = 0; j < a->val.object.count; j++) {
                if (strcmp(a->val.object.pairs[j].key, b->val.object.pairs[i].key) == 0) {
                    existing = &a->val.object.pairs[j]; break;
                }
            }
            if (existing) {
                json_node *merged = merge(existing->value, b->val.object.pairs[i].value);
                if (merged != existing->value) existing->value = merged;
            } else {
                a->val.object.pairs = realloc(a->val.object.pairs, sizeof(json_pair) * (a->val.object.count + 1));
                a->val.object.pairs[a->val.object.count].key = strdup(b->val.object.pairs[i].key);
                a->val.object.pairs[a->val.object.count].value = copy_node(b->val.object.pairs[i].value);
                a->val.object.count++;
