        if (**s == '\\') {
            (*s)++;
            if (**s == 'n') buf[len++] = '\n';
            else if (**s == 'r') buf[len++] = '\r';
            else if (**s == 't') buf[len++] = '\t';
            else if (**s == '\\') buf[len++] = '\\';
            else if (**s == '"') buf[len++] = '"';
            else buf[len++] = **s;
        } else buf[len++] = **s;
        (*s)++;
    }
    buf[len] = '\0';
    if (**s == '"') (*s)++;
    return strdup(buf);
