        node->type = JSON_OBJECT; node->val.object.count = 0; node->val.object.pairs = NULL;
        (*s)++;
        while (**s && **s != '}') {
            while (*s && (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r')) (*s)++;
            if (**s == '}') break;
            char *key = parse_string(s);
