            if (**s == ':') (*s)++;
            node->val.object.pairs = realloc(node->val.object.pairs, sizeof(json_pair) * (node->val.object.count + 1));
            node->val.object.pairs[node->val.object.count].key = key;
            node->val.object.pairs[node->val.object.count].value = parse_json(s);
            node->val.object.count++;
            while (*s && (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r')) (*s)++;
            if (**s == ',') (*s)++;
        }
        if (**s == '}') (*s)++;
    } else if (**s == '[') {
        node->type = JSON_ARRAY; node->val.array.count = 0; node->val.array.elements = NULL;
        (*s)++;
        while (**s && **s != ']') {
            while (*s && (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r')) (*s)++;
            if (**s == ']') break;
            node->val.array.elements = realloc(node->val.array.elements, sizeof(json_node) * (node->val.array.count + 1));
