            while (*s && (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r')) (*s)++;
            if (**s == ',') (*s)++;
        }
        if (**s == ']') (*s)++;
    } else if (**s == '"') {
        node->type = JSON_STRING; node->val.s_val = parse_string(s);
    } else if (strncmp(*s, "true", 4) == 0) {
        node->type = JSON_BOOL; node->val.b_val = true; *s += 4;
    } else if (strncmp(*s, "false", 5) == 0) {
        node->type = JSON_BOOL; node->val.b_val = false; *s += 5;
    } else if (strncmp(*s, "null", 4) == 0) {
