    } else {
        node->type = JSON_NUMBER;
        char buf[128]; int i = 0;
        while (**s && !strchr(",]} \t\n\r", **s)) buf[i++] = *(*s)++;
        buf[i] = '\0'; node->val.d_val = atof(buf);
    }
    return node;
}

