            if (node->type == JSON_BOOL) { printf("%s", node->val.b_val ? "true" : "false"); return; }
            if (node->type == JSON_NUMBER) { printf("%g", node->val.d_val); return; }
            if (node->type == JSON_STRING) { printf("\"%s\"", node->val.s_val); return; }

            if (node->type == JSON_ARRAY) {
                printf("[\n");
                for (size_t i = 0; i < node->val.array.count; i++) {
                    printf("%*s", (indent + 1) * 2, "");
                    print_json(&node->val.array.elements[i], indent + 1);
                    if (i < node->val.array.count - 1) printf(",");
                    printf("\n");
                }
                // Wait, if print_json(element) is an object, it'll print its own newline.
                // So if element is an object:
                // print_json(element) -> '{' + '\n' + '  "key": "val"' + '\n' + '}'
                // Then the array's loop will print:
                // '  ' + '{' + '\n' + '    "key": "val"' + '\n' + '  }' + ',' + '\n'
                // This is perfect!
            }
            if (node->type == JSON_OBJECT) {
                printf("{\n");
                for (size_t i = 0; i < node->val.object.count; i++) {
                    printf("%*s", (indent + 1) * 2, "");
                    printf("\"%s\": ", node->val.object.pairs[i].key);
                    print_json(node->val.object.pairs[i].value, indent + 1);
                    if (i < node->val.object.count - 1) printf(",");
                    printf("\n");
                }
            }
        }

bool is_equal(const json_node *a, const json_node *b) {
            if (a->type != b->type) return false;
            if (a->type == JSON_NULL) return true;
            if (a->type == JSON_BOOL) return a->val.b_val == b->val.b_val;
            if (a->type == JSON_NUMBER) return a->val.d_val == b->val.d_val;
            if (a->type == JSON_STRING) return strcmp(a->val.s_val, b->val.s_val) == 0;
            if (a->type == JSON_ARRAY) {
                if (a->val.array.count != b->val.array.count) return false;
                for (size_t i = 0; i < a->val.array.count; i++) {
                    if (!is_equal(&a->val.array.elements[i], &b->val.array.elements[i])) return false;
