json_node* copy_node(const json_node *src) {
        json_node *res = malloc(sizeof(json_node));
        res->type = src->type;
        if (src->type == JSON_NULL) {}
        else if (src->type == JSON_BOOL) res->val.b_val = src->val.b_val;
        else if (src->type == JSON_NUMBER) res->val.d_val = src->val.d_val;
        else if (src->type == JSON_STRING) res->val.s_val = strdup(src->val.s_val);
        else if (src->type == JSON_ARRAY) {
            res->val.array.count = src->val.array.count;
            res->val.array.elements = malloc(sizeof(json_node*) * src->val.array.count);
            for (size_t i = 0; i < src->val.array.count; i++) {
                res->val.array.elements[i] = copy_node(src->val.array.elements[i]);
            }
        } else if (src->type == JSON_OBJECT) {
            res->val.object.count = src->val.object.count;
            res->val.object.pairs = malloc(sizeof(json_pair) * src->val.object.count);
            for (size-t i = 0; i < src->val.object.count; i++) {
                res->val.object.pairs[i].key = strdup(src->val.object.pairs[i].key);
                res->val.object.pairs[i].value = copy_node(src->val.object.pairs[i].value);
