function main() {
  const results: FileInfo[] = [];
  walk(rootDir, rootDir, results);

  console.log('=== File Tree Analysis ===');
  console.log('');

  const groups: { [ext: string]: FileInfo[] } = {};
  for (const f of results) {
    if (!groups[f.ext]) {
      groups[f.ext] = [];
    }
    groups[f.ext].push(f);
  }

  const sortedExts = Object.keys(groups).sort();

  for (const ext of sortedExts) {
    const groupFiles = groups[ext].sort((a, b) => a.relPath.localeCompare(b.relPath));
    let gFiles = 0;
    let gLines = 0;
    let gChars = 0;

    for (const f of groupFiles) {
      gFiles++;
      gLines += f.lines;
      gChars += f.chars;
    }

    console.log(`Extension: ${ext}`);
    console.log(`  Files: ${gFiles}`);
    console.log(`  Total Lines: ${gLines}`);
    console.log(`  Total Characters: ${gChars}`);
    for (const f of groupFiles) {
      console.log(`    ${f.relPath}: ${f.lines} lines, ${f.chars} chars`);
    }
  }

  let totalFiles = results.length;
  let totalLines = results.reduce((sum, f) => sum + f.lines, 0);
  let totalChars = results.reduce((sum, f) => sum + f.chars, 0);

  console.log('');
  console.log(`Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters`);
}

