public class Main {
    public static void main(String[] args) {
        int[][] A = {
            {1, 2, 3},
            {4, 5, 6},
            {7, 8, 9}
        };
        int[][] B = {
            {9, 8, 7},
            {6, 5, 4},
            {3, 2, 1}
        };

        // Compute C = A x B
        int[][] C = new int[3][3];
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                for (int k = 0; k < 3; k++) {
                    C[i][j] += A[i][k] * B[k][j];
                }
            }
        }

        // Compute Determinant of C
        // det = a(ei - fh) - b(di - fg) + c(dh - eg)
        int det = C[0][0] * (C[1][1] * C[2][2] - C[1][2] * C[2][1])
                - C[0][1] * (C[1][0] * C[2][2] - C[1][2] * C[2][0])
                + C[0][2] * (C[1][0] * C[2][1] - C[1][1] * C[2][0]);

        // Output formatting
        System.out.println("=== Matrix Operations ===");
        System.out.println();

        System.out.println("Matrix A:");
        for (int i = 0; i < 3; i++) {
            System.out.printf("  %4d %4d %4d%n", A[i][0], A[i][1], A[i][2]);
        }
        System.out.println();

        System.out.println("Matrix B:");
        for (int i = 0; i < 3; i++) {
            System.out.printf("  %4d %4d %4d%n", B[i][0], B[i][1], B[i][2]);
        }
        System.out.println();

        System.out.println("A x B =");
        for (int i = 0; i < 3; i++) {
            System.out.printf("  %4d %4d %4d%n", C[i][0], C[i][1], C[i][2]);
        }
        System.out.println();

        System.out.println("Determinant: " + det);
