        struct stat st;
        if (lstat(path, &st) !=  | 0) continue;

        if (S_ISDIR(st.st_mode)) {
            walk(path, base_path);
        } else if (S_ISREG(st.st_mode)) {
            // Calculate rel_path
            size_t len_base = strlen(base_path);
            char *rel_path = path + len_base;
            if (*rel_path == '/') rel_path++;

            // Calculate extension
