            if (!q1 || q1 >= nodes_end) break;
            char* q2 = strchr(q1 + 1, '\"');
            if (!q2 || q2 >= nodes_end) break;
            int len = q2 - q1 - 1;
            node_names[node_count] = malloc(len + 1);
            strncpy(node_names[node_count], q1 + 1, len);
            node_names[node_count][len] = '\0';
            node_count++;
            curr = q2 + 1;
        }
    }

    char* edges_start = strstr(buf, "\"edges\": [");
    if (edges_start) edges_start += 9;
    char* edges_end = strrchr(buf, ']');

    AdjList* adj = calloc(node_count, sizeof(AdjList));
    if (edges_start && edges_end) {
        char* curr_e = edges_start;
        while (curr_e && curr_e < edges_end) {
            char* f_key = strstr(curr_e, "\"from\":\"");
            if (!f_key || f_key >= edges_end) break;
            char* t_key = strstr(curr_e, "\"to\":\"");
            if (!t_key || t_key >= edges_end) break;
            char* w_key = strstr(curr_e, "\"weight\":");
            if (!w_key || w_key >= edges_end) break;

            char from_name[256] = {0};
            char to_name[256] = {0};
            double weight = 0;

            char* f_val_start = f_key + 8;
            char* f_val_end = strchr(f_val_start, '\"');
            if (f_val_end) {
                int len_f = f_val_end - f_val_start;
                strncpy(from_name, f_val_start, len_f);
                from_name[len_f] = '\0';
            }

            char* t_val_start = t_key + 6;
            char* t_val_end = strchr(t_val_start, '\"');
            if (t_val_end) {
                int len_t = t_val_end - t_val_start;
                strncpy(to_name, t_val_start, len_t);
                to_name[len_t] = '\0';
            }

            char* w_val_start = strchr(w_key, ':') + 1;
            while (*w_val_start == ' ' || *w_val_start == ':') w_val_start++;
            weight = atof(w_val_start);

            int u = -1, v = -1;
            for (int i = 0; i < node_count; i++) {
                if (strcmp(node_names[i], from_name) == 0) u = i;
                if (strcmp(node_names[i], to_name) == 0) v = i;
            }

            if (u != -1 && v != -1) {
                Edge* e1 = malloc(sizeof(Edge));
                e1->to = v; e1->weight = weight; e1->next = adj[u].head; adj[u].head = e1;
                Edge* e2 = malloc(sizeof(Edge));
                e2->to = u; e2->weight = weight; e2->next = adj[v].head; adj[v].head = e2;
            }
            char* next_obj = strchr(f_key, '}');
            if (next_obj && next_obj < edges_end) curr_e = next_obj + 1;
            else break;
        }
    }

    int source_id = -1;
    for (int i = 0; i < node_count; i++) {
        if (strcmp(node_names[i], "A") == 0) {
            source_id = i;
            break;
        }
    }

    double* dists = malloc(node_count * sizeof(double));
    for (int i = 0; i < node_count; i++) dists[i] = DBL_MAX;

    if (source_id != -1) {
        dists[source_id] = 0;
        MinHeap heap;
        heap.data = malloc(1000000 * sizeof(HeapNode));
        heap.size = 0;
        push(&heap, source_id, 0);

        while (heap.size > 0) {
            HeapNode top = pop(&heap);
            int u = top.node;
            double d = top.dist;
            if (d > dists[u]) continue;

            Edge* e = adj[u].head;
            while (e) {
                if (dists[u] + e->weight < dists[e->to]) {
                    dists[e->to] = dists[u] + e->weight;
                    push(&heap, e->to, dists[e->to]);
                }
                e = e->next;
            }
        }
        free(heap.data);
    }

    Result* results = malloc(node_count * sizeof(Result));
    for (int i = 0; i < node_count; i++) {
        results[i].name = node_names[i];
        results[i].dist = dists[i];
    }
    qsort(results, node_count, sizeof(Result), compare_results);

    printf("=== Shortest Paths from A ===\n\n");
    for (int i = 0; i < node_count; i++) {
        printf("A -> %s: %g\n", results[i].name, results[i].dist);
    }

    return 0;
}
